// Arma el payload del recordatorio desde la lectura fresca del doc.
// Devuelve [] (termina la rama) si la reserva ya no está vigente.
const norm = $('Normalizar entrada').first().json;
const document_id = String(norm.document_id || '').trim();
const raw = ($input.first() || {}).json || {};

const getField = (d, k) => {
  if (!d || typeof d !== 'object') return null;
  if (d.fields && d.fields[k] !== undefined) {
    const f = d.fields[k];
    if (f === null || f === undefined) return null;
    if (f.stringValue !== undefined) return f.stringValue;
    if (f.integerValue !== undefined) return parseInt(f.integerValue);
    if (f.booleanValue !== undefined) return f.booleanValue;
    if (f.doubleValue !== undefined) return parseFloat(f.doubleValue);
    return null;
  }
  return d[k] !== undefined ? d[k] : null;
};

const normalizePhone = (v) => {
  let s = String(v || '').replace(/@s\.whatsapp\.net$/i, '').replace(/[^0-9]/g, '');
  if (!s) return '';
  if (s.startsWith('0')) s = s.slice(1);
  if (s.startsWith('54')) return s;
  return '54' + s;
};

if (!document_id) return [];
const estado = String(getField(raw, 'estado') || '').toLowerCase();
// Cancelada/finalizada/ausente, o doc eliminado (raw trae {error}): no avisar.
if (!raw || raw.error) return [];
if (['cancelado', 'cancelada', 'no_show', 'ausente', 'finalizado'].includes(estado)) return [];

const time = getField(raw, 'time');
const name = String(getField(raw, 'customerName') || '').trim();
const phone = normalizePhone(getField(raw, 'customerPhone') || getField(raw, 'phone'));
const mesaRaw = String(getField(raw, 'mesa') || getField(raw, 'tableId') || getField(raw, 'mesa_id') || '');
if (!time || !phone || !name) return [];
if (estado === 'pendiente' && !mesaRaw) return []; // nunca fue confirmada
const mesaNum = mesaRaw.replace(/^mesa\s+/i, '').replace(/^m(?=\d)/i, '');

return [{ json: {
  document_id,
  reminder_key: 'reminder15_' + document_id,
  phone,
  name,
  time,
  mesa: mesaNum,
} }];
